  "Du får maten på en bricka och sätter dig vid ett bord eller i fönstret med utsikt över havet. Mättnaden och energin kommer medan du äter – och när allt är uppätet blir du gladare!": "Tu reçois ton repas sur un plateau et tu t'assois à une table ou près de la fenêtre, avec vue sur la mer. La satiété et l'énergie arrivent pendant que tu manges – et quand tu as tout fini, tu es de meilleure humeur!",
  "Du får maten på en bricka och sätter dig vid ett ledigt bord eller vid fönstret. Mättnaden och energin kommer medan du äter – bara när du sitter!": "Tu reçois ton repas sur un plateau et tu t'installes à une table libre ou près de la fenêtre. La satiété et l'énergie arrivent pendant que tu manges – seulement si tu restes à table !",
