  "Välj din avatar eller skapa en ny.": "Choisis ton avatar ou crée-en un nouveau.",
  "Välj en fröpåse. Vattna bädden varje dag – två dagar utan vatten och plantorna vissnar. Skörden hamnar i skafferiet.": "Choisis un sachet de graines. Arrose le carré chaque jour – deux jours sans eau et les plants fanent. La récolte va dans le garde-manger.",
