  "Välj en låt – den går hemma tills du stänger av eller lägger dig. Alla låtar i Pixelstaden finns här.": "Choisis une chanson – elle passe à la maison jusqu'à ce que tu l'arrêtes ou que tu ailles te coucher. Toutes les chansons de Pixelville sont ici.",
