  "💬 Alla djur här är ungar. De växer av mat, lek, en leksak och rätt toalett – tidigast unga efter 3 dagar och vuxna efter en vecka.": "💬 Tous les animaux ici sont des bébés. Ils grandissent avec de la nourriture, des jeux, un jouet et le bon coin toilette – jeunes après 3 jours au plus tôt, adultes après une semaine.",
  "💬 Djuren har en liten mätare ovanför sig: hjärtat är glädje och skålen är hunger.": "💬 Les animaux ont une petite jauge au-dessus d'eux : le cœur, c'est la joie, et la gamelle, c'est la faim.",
  "💬 Har du en hane och en hona av samma art kan de bli kära – och få ungar!": "💬 Si tu as un mâle et une femelle de la même espèce, ils peuvent tomber amoureux – et avoir des petits !",
  "💬 Hundar måste ut på promenad i koppel, annars blir det olyckor inne.": "💬 Les chiens doivent sortir en laisse pour se promener, sinon il y a des accidents à la maison.",
  "💬 Kaniner jagar inga bollar – men de älskar att gnaga på en gnagmorot!": "💬 Les lapins ne courent pas après les balles – mais ils adorent grignoter une carotte à ronger !",
  "💬 Kaniner trivs bäst i en bur med halm. Byt halm ibland så blir de glada.": "💬 Les lapins se plaisent dans une cage avec de la paille. Change la paille de temps en temps, ça les rend heureux.",
  "💬 Katter behöver en kattlåda – och den måste tömmas ibland!": "💬 Les chats ont besoin d'une litière – et il faut la vider de temps en temps !",
  "💬 Katter gillar att klättra – ett klösträd gör dem gladare.": "💬 Les chats adorent grimper – un arbre à chat les rend plus heureux.",
  "💬 Maten: klicka på säcken hemma så bär du den, klicka sen på skålen så häller du upp.": "💬 La nourriture : à la maison, clique sur le sac pour le porter, puis sur la gamelle pour la remplir.",
